    (forall x, p - 16 <= x < p - 12 -> ~ art_enq_fp newb (S - 2208) t spb ris qs km b L B cntB x) ->
    (* [comment removed for export] *)
    DInvK l2 blk (Datatypes.S kb) Dz M0 -> DRoD M0 ->
    (* [comment removed for export] *)
    (forall regs' (M' : word -> option byte),
