        getr regs' 10 = Z_to_bv 64 0x13e670 -> getr regs' 11 = Z_to_bv 64 c -> getr regs' 12 = Z_to_bv 64 ca -> getr regs' 13 = Z_to_bv 64 (S - 2128) ->
        (forall r : reg, In r [3; 4; 23; 24; 25; 26; 27]%bv -> getr regs' r = getr regs r) ->
        2 ^ 20 < bytes' ->
        art_free3_outK M0 M' S t p q16 qr l2 blk b1 n spb ris qs km L B cntB bszB bytes kb Dz inited cl ->
        art_free3_epi M' S p raw0 regs -> wrA M' (S - 4096) 4096 ->
        aruns ASEGS EVOK GR Q (log ++ art_enq_events newb spb cl) (mkst regs' (0x54a98 : word) M' rom)) ->
    aruns ASEGS EVOK GR Q log (mkst regs (0x7a1a8 : word) M0 rom).
